({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [perfil, setPerfil] = useState({ nombre: '', avatar_url: '', cargo: '' });
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [mensaje, setMensaje] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`);
    if (res.ok && res.registros.length > 0) {
      setPerfil(res.registros[0]);
    }
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setGuardando(true);
    setMensaje(null);
    const payload = {
      id: perfil.id || `perf_${miId}`,
      usuario_id: miId,
      nombre: perfil.nombre,
      avatar_url: perfil.avatar_url,
      cargo: perfil.cargo
    };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`, {
      method: perfil.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setMensaje({ texto: MEITI.t('profile_saved', null, 'Perfil actualizado correctamente.'), tono: 'exito' });
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setMensaje({ texto: err || MEITI.t('error_saving', null, 'Error al guardar.'), tono: 'peligro' });
        setGuardando(false);
      }
    });
  };

  if (cargando) return <UI.Tarjeta><div className="p-4 text-center"><Iconos.Loader className="animate-spin mx-auto" color={tema.colorPrimario} /></div></UI.Tarjeta>;

  return (
    <UI.Tarjeta>
      <div className="flex items-center gap-3 mb-4">
        <Iconos.UserCircle size={24} color={tema.colorPrimario} />
        <h2 className="text-xl font-bold" style={{ color: tema.texto }}>{MEITI.t('my_profile', null, 'Mi Perfil')}</h2>
      </div>
      {mensaje && <UI.Aviso mensaje={mensaje.texto} tono={mensaje.tono} onCerrar={() => setMensaje(null)} />}
      <form onSubmit={guardar} className="flex flex-col gap-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('display_name', null, 'Nombre a mostrar')} tipo="text" valor={perfil.nombre} onChange={e => setPerfil({...perfil, nombre: e.target.value})} placeholder="Ej: Ana Gómez" />
          </div>
          <div className="flex-1">
            <UI.Campo etiqueta={MEITI.t('job_title', null, 'Cargo / Rol')} tipo="text" valor={perfil.cargo} onChange={e => setPerfil({...perfil, cargo: e.target.value})} placeholder="Ej: Contadora Senior" />
          </div>
          <div className="md:col-span-2 flex-1">
            <UI.Campo etiqueta={MEITI.t('avatar_url', null, 'URL del Avatar (opcional)')} tipo="text" valor={perfil.avatar_url} onChange={e => setPerfil({...perfil, avatar_url: e.target.value})} placeholder="https://..." />
          </div>
        </div>
        <div className="flex justify-end">
          <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
            <span className="flex items-center gap-2"><Iconos.Save size={16} /> {guardando ? MEITI.t('saving', null, 'Guardando...') : MEITI.t('save_profile', null, 'Guardar Perfil')}</span>
          </UI.Boton>
        </div>
      </form>
    </UI.Tarjeta>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [canales, setCanales] = useState([]);
  const [mensajes, setMensajes] = useState([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const cargar = async () => {
      const [resCanales, resMensajes] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`)
      ]);
      if (resCanales.ok) setCanales(resCanales.registros);
      if (resMensajes.ok) setMensajes(resMensajes.registros);
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) {
    return (
      <UI.Tarjeta>
        <div className="p-8 flex justify-center items-center">
          <i className="fa-solid fa-circle-notch fa-spin text-4xl" style={{ color: tema.colorPrimario }}></i>
        </div>
      </UI.Tarjeta>
    );
  }

  const misDms = mensajes.filter(m => !m.canal_id && m.receptor_id === miId);
  const mensajesRecientes = mensajes.filter(m => m.canal_id).sort((a, b) => new Date(b.fecha_registro) - new Date(a.fecha_registro)).slice(0, 5);

  return (
    <div className="flex flex-col gap-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <UI.Tarjeta className="flex flex-col items-center justify-center p-6 text-center">
          <i className="fa-solid fa-hashtag text-3xl mb-2" style={{ color: tema.colorPrimario }}></i>
          <span className="text-3xl font-black" style={{ color: tema.texto }}>{canales.length}</span>
          <span className="text-sm opacity-70 uppercase tracking-wider font-bold mt-1" style={{ color: tema.texto }}>
            {MEITI.t('active_channels', null, 'Canales Activos')}
          </span>
        </UI.Tarjeta>
        <UI.Tarjeta className="flex flex-col items-center justify-center p-6 text-center">
          <i className="fa-solid fa-message text-3xl mb-2" style={{ color: tema.colorSecundario }}></i>
          <span className="text-3xl font-black" style={{ color: tema.texto }}>{misDms.length}</span>
          <span className="text-sm opacity-70 uppercase tracking-wider font-bold mt-1" style={{ color: tema.texto }}>
            {MEITI.t('direct_messages', null, 'Mensajes Directos')}
          </span>
        </UI.Tarjeta>
        <UI.Tarjeta className="flex flex-col items-center justify-center p-6 text-center">
          <i className="fa-solid fa-at text-3xl mb-2" style={{ color: tema.colorPrimario }}></i>
          <span className="text-3xl font-black" style={{ color: tema.texto }}>0</span>
          <span className="text-sm opacity-70 uppercase tracking-wider font-bold mt-1" style={{ color: tema.texto }}>
            {MEITI.t('mentions', null, 'Menciones Nuevas')}
          </span>
        </UI.Tarjeta>
      </div>

      <UI.Tarjeta>
        <div className="flex items-center gap-2 mb-4">
          <i className="fa-solid fa-chart-line text-xl" style={{ color: tema.colorSecundario }}></i>
          <h3 className="font-bold text-lg" style={{ color: tema.texto }}>
            {MEITI.t('recent_activity', null, 'Actividad Reciente')}
          </h3>
        </div>
        {mensajesRecientes.length === 0 ? (
          <UI.EstadoVacio icono="fa-comment-slash" mensaje={MEITI.t('no_recent_activity', null, 'No hay actividad reciente en los canales.')} />
        ) : (
          <div className="flex flex-col gap-3">
            {mensajesRecientes.map(m => {
              const canal = canales.find(c => c.id === m.canal_id);
              return (
                <div key={m.id} className="p-3 rounded-xl flex flex-col gap-1" style={{ backgroundColor: tema.texto + '08' }}>
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-bold px-2 py-1 rounded-md" style={{ backgroundColor: tema.colorPrimario + '22', color: tema.colorPrimario }}>
                      #{canal?.nombre || MEITI.t('unknown', null, 'Desconocido')}
                    </span>
                    <span className="text-xs opacity-50" style={{ color: tema.texto }}>
                      {new Date(m.fecha_registro).toLocaleDateString()}
                    </span>
                  </div>
                  <p className="text-sm line-clamp-2 mt-1" style={{ color: tema.texto }}>{m.texto}</p>
                </div>
              );
            })}
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();

  const [canales, setCanales] = useState([]);
  const [mensajes, setMensajes] = useState([]);
  const [perfiles, setPerfiles] = useState([]);
  const [prefs, setPrefs] = useState({ canal_activo: null });
  const [nuevoMensaje, setNuevoMensaje] = useState('');
  const [cargando, setCargando] = useState(true);
  const [enviando, setEnviando] = useState(false);

  const cargarTodo = async () => {
    const [resCan, resMsgs, resPerf, resPrefs] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`)
    ]);

    if (resCan.ok) setCanales(resCan.registros);
    if (resPerf.ok) setPerfiles(resPerf.registros);

    let canalActivoId = null;
    if (resPrefs.ok && resPrefs.registros.length > 0) {
      setPrefs(resPrefs.registros[0]);
      canalActivoId = resPrefs.registros[0].canal_activo;
    }

    if (!canalActivoId && resCan.ok && resCan.registros.length > 0) {
      canalActivoId = resCan.registros[0].id;
      cambiarCanal(canalActivoId, resPrefs.registros[0]?.id);
    }

    if (resMsgs.ok && canalActivoId) {
      setMensajes(resMsgs.registros.filter(m => m.canal_id === canalActivoId && !m.hilo_id).sort((a, b) => new Date(a.fecha_registro) - new Date(b.fecha_registro)));
    }
    setCargando(false);
  };

  useEffect(() => {
    cargarTodo();
    const interval = setInterval(cargarTodo, 5000);
    return () => clearInterval(interval);
  }, []);

  const cambiarCanal = async (canalId, prefId = prefs.id) => {
    setCargando(true);
    const payload = { id: prefId || `pref_${miId}`, usuario_id: miId, canal_activo: canalId };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`, {
      method: prefId ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setPrefs(payload); cargarTodo(); }
    });
  };

  const enviarMensaje = async () => {
    if (!nuevoMensaje.trim() || !prefs.canal_activo) return;
    setEnviando(true);
    const payload = {
      id: `msg_${Date.now()}`,
      canal_id: prefs.canal_activo,
      autor_id: miId,
      usuario_id: miId,
      texto: nuevoMensaje.trim(),
      fecha_registro: new Date().toISOString()
    };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setNuevoMensaje(''); cargarTodo(); setEnviando(false); },
      alFallar: () => setEnviando(false)
    });
  };

  const canalActual = canales.find(c => c.id === prefs.canal_activo);

  const historialMapeado = mensajes.map(m => {
    const autor = perfiles.find(p => p.usuario_id === m.autor_id) || { nombre: MEITI.t('unknown_user', null, 'Usuario'), avatar_url: 'avatares/toon_1.png' };
    return {
      id: m.id,
      texto: m.texto,
      esMio: m.autor_id === miId,
      autor: autor.nombre,
      avatar: autor.avatar_url || 'avatares/toon_1.png',
      fecha: m.fecha_registro
    };
  });

  return (
    <div className="flex flex-col md:flex-row gap-4 h-full min-h-0">
      <UI.Tarjeta className="md:w-64 flex flex-col gap-2 min-h-0">
        <div className="text-xs uppercase tracking-wider opacity-60 px-2 py-1 font-bold" style={{ color: tema.texto }}>
          {MEITI.t('channels', null, 'Canales')}
        </div>
        <div className="flex-1 overflow-y-auto flex flex-col gap-1 min-h-0">
          {canales.length === 0 ? (
            <UI.EstadoVacio icono="fa-hashtag" mensaje={MEITI.t('no_channels', null, 'No hay canales disponibles')} />
          ) : (
            canales.map(c => (
              <button 
                key={c.id} 
                onClick={() => cambiarCanal(c.id)}
                className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-bold transition-colors text-left"
                style={{ 
                  backgroundColor: prefs.canal_activo === c.id ? tema.colorPrimario + '22' : 'transparent', 
                  color: prefs.canal_activo === c.id ? tema.colorPrimario : tema.texto 
                }}
              >
                <i className="fa-solid fa-hashtag opacity-70 text-xs"></i>
                <span className="truncate">{c.nombre}</span>
              </button>
            ))
          )}
        </div>
      </UI.Tarjeta>

      <UI.Tarjeta className="flex-1 flex flex-col min-h-0 p-0 overflow-hidden">
        {cargando && mensajes.length === 0 ? (
          <div className="flex-1 flex items-center justify-center">
            <i className="fa-solid fa-circle-notch fa-spin text-3xl" style={{ color: tema.colorPrimario }}></i>
          </div>
        ) : !canalActual ? (
          <UI.EstadoVacio icono="fa-hashtag" mensaje={MEITI.t('select_channel', null, 'Selecciona un canal para empezar')} />
        ) : (
          <div className="flex flex-col flex-1 min-h-0">
            <div className="p-4 border-b flex items-center gap-3 shadow-sm z-10" style={{ borderColor: tema.texto + '11', backgroundColor: tema.superficie }}>
              <i className="fa-solid fa-hashtag text-xl" style={{ color: tema.colorPrimario }}></i>
              <div>
                <h2 className="font-bold text-lg leading-tight" style={{ color: tema.texto }}>{canalActual.nombre}</h2>
                <p className="text-xs opacity-60" style={{ color: tema.texto }}>{canalActual.descripcion || MEITI.t('no_description', null, 'Sin descripción')}</p>
              </div>
            </div>

            <div className="flex-1 min-h-0 flex flex-col">
              <UI.Chat 
                historial={historialMapeado} 
                valor={nuevoMensaje} 
                onCambio={(v) => setNuevoMensaje(v?.target ? v.target.value : v)} 
                onEnviar={enviarMensaje} 
                escribiendo={enviando} 
              />
            </div>
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [hiloId, setHiloId] = useState(null);
  const [mensajePadre, setMensajePadre] = useState(null);
  const [respuestas, setRespuestas] = useState([]);
  const [perfiles, setPerfiles] = useState([]);
  const [nuevaRespuesta, setNuevaRespuesta] = useState('');
  const [cargando, setCargando] = useState(true);
  const [enviando, setEnviando] = useState(false);

  const cargar = async () => {
    const [resPrefs, resMsgs, resPerf] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`)
    ]);

    if (resPerf.ok) setPerfiles(resPerf.registros);

    if (resPrefs.ok && resPrefs.registros.length > 0) {
      const idActivo = resPrefs.registros[0].hilo_activo;
      setHiloId(idActivo);
      if (resMsgs.ok && idActivo) {
        const padre = resMsgs.registros.find(m => m.id === idActivo);
        const resps = resMsgs.registros.filter(m => m.hilo_id === idActivo).sort((a, b) => new Date(a.fecha_registro) - new Date(b.fecha_registro));
        setMensajePadre(padre);
        setRespuestas(resps);
      }
    }
    setCargando(false);
  };

  useEffect(() => {
    cargar();
    const interval = setInterval(cargar, 5000);
    return () => clearInterval(interval);
  }, []);

  const enviarRespuesta = async (e) => {
    e.preventDefault();
    if (!nuevaRespuesta.trim() || !hiloId) return;
    setEnviando(true);
    const payload = {
      id: `msg_${Date.now()}`,
      canal_id: mensajePadre?.canal_id,
      hilo_id: hiloId,
      autor_id: miId,
      texto: nuevaRespuesta.trim(),
      fecha_registro: new Date().toISOString()
    };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setNuevaRespuesta(''); cargar(); setEnviando(false); },
      alFallar: () => setEnviando(false)
    });
  };

  if (cargando) return <UI.Tarjeta><div className="p-8 text-center"><Iconos.Loader className="animate-spin mx-auto" color={tema.colorPrimario} /></div></UI.Tarjeta>;
  if (!mensajePadre) return <UI.Tarjeta><UI.EstadoVacio icono="fa-thread" mensaje={MEITI.t('no_thread_selected', null, 'No hay ningún hilo seleccionado.')} /></UI.Tarjeta>;

  const autorPadre = perfiles.find(p => p.usuario_id === mensajePadre.autor_id) || { nombre: 'Usuario', avatar_url: 'avatares/toon_1.png' };

  return (
    <UI.Tarjeta className="flex flex-col p-0 overflow-hidden">
      <div className="p-4 border-b flex items-center gap-3 shadow-sm z-10" style={{ borderColor: tema.texto + '11', backgroundColor: tema.superficie }}>
        <button onClick={() => MEITI.irAPagina('canal')} className="p-2 rounded-full hover:bg-black/5 transition-colors">
          <Iconos.ArrowLeft size={20} color={tema.texto} />
        </button>
        <h2 className="font-bold text-lg" style={{ color: tema.texto }}>{MEITI.t('thread', null, 'Hilo')}</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-6">
        <div className="flex gap-3 pb-6 border-b" style={{ borderColor: tema.texto + '11' }}>
          <img src={autorPadre.avatar_url || 'avatares/toon_1.png'} alt="avatar" className="w-12 h-12 rounded-xl object-cover flex-shrink-0" />
          <div className="flex flex-col">
            <div className="flex items-baseline gap-2 mb-1">
              <span className="text-base font-bold" style={{ color: tema.texto }}>{autorPadre.nombre}</span>
              <span className="text-xs opacity-50" style={{ color: tema.texto }}>{new Date(mensajePadre.fecha_registro).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
            </div>
            <p className="text-base" style={{ color: tema.texto }}>{mensajePadre.texto}</p>
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <span className="text-xs font-bold opacity-50 uppercase tracking-wider" style={{ color: tema.texto }}>{respuestas.length} {MEITI.t('replies', null, 'Respuestas')}</span>
          {respuestas.map(r => {
            const autor = perfiles.find(p => p.usuario_id === r.autor_id) || { nombre: 'Usuario', avatar_url: 'avatares/toon_1.png' };
            return (
              <div key={r.id} className="flex gap-3">
                <img src={autor.avatar_url || 'avatares/toon_1.png'} alt="avatar" className="w-8 h-8 rounded-lg object-cover flex-shrink-0 mt-1" />
                <div className="flex flex-col">
                  <div className="flex items-baseline gap-2">
                    <span className="text-sm font-bold" style={{ color: tema.texto }}>{autor.nombre}</span>
                    <span className="text-xs opacity-50" style={{ color: tema.texto }}>{new Date(r.fecha_registro).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                  </div>
                  <p className="text-sm" style={{ color: tema.texto }}>{r.texto}</p>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="p-4 border-t" style={{ borderColor: tema.texto + '11', backgroundColor: tema.superficie }}>
        <form onSubmit={enviarRespuesta} className="flex gap-2">
          <div className="flex-1">
            <UI.Campo tipo="text" valor={nuevaRespuesta} onChange={e => setNuevaRespuesta(e.target.value)} placeholder={MEITI.t('reply_placeholder', null, 'Responde a este hilo...')} />
          </div>
          <UI.Boton tipo="submit" variante="primario" disabled={enviando || !nuevaRespuesta.trim()}>
            <Iconos.Send size={18} />
          </UI.Boton>
        </form>
      </div>
    </UI.Tarjeta>
  );
}

