      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`)
    ]);

    if (resPerf.ok) setPerfiles(resPerf.registros.filter(p => p.usuario_id !== miId));

    let dmActivoId = null;
    if (resPrefs.ok && resPrefs.registros.length > 0) {
      setPrefs(resPrefs.registros[0]);
      dmActivoId = resPrefs.registros[0].dm_activo;
    }

    if (resMsgs.ok && dmActivoId) {
      setMensajes(resMsgs.registros.filter(m => !m.canal_id && ((m.autor_id === miId && m.receptor_id === dmActivoId) || (m.autor_id === dmActivoId && m.receptor_id === miId))).sort((a, b) => new Date(a.fecha_registro) - new Date(b.fecha_registro)));
    }
    setCargando(false);
  };

  useEffect(() => {
    cargarTodo();
    const interval = setInterval(cargarTodo, 5000);
    return () => clearInterval(interval);
  }, []);

  const cambiarDM = async (usuarioId, prefId = prefs.id) => {
    setCargando(true);
    const payload = { id: prefId || `pref_${miId}`, usuario_id: miId, dm_activo: usuarioId };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`, {
      method: prefId ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setPrefs(payload); cargarTodo(); }
    });
  };

  const enviarMensaje = async (e) => {
    e.preventDefault();
    if (!nuevoMensaje.trim() || !prefs.dm_activo) return;
    setEnviando(true);
    const payload = {
      id: `msg_${Date.now()}`,
      canal_id: null,
      receptor_id: prefs.dm_activo,
      autor_id: miId,
      texto: nuevoMensaje.trim(),
      fecha_registro: new Date().toISOString()
    };
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { setNuevoMensaje(''); cargarTodo(); setEnviando(false); },
      alFallar: () => setEnviando(false)
    });
  };

  const perfilActivo = perfiles.find(p => p.usuario_id === prefs.dm_activo);

  return (
    <div className="flex flex-col md:flex-row gap-4">
      <UI.Tarjeta className="md:w-64 flex flex-col gap-2 overflow-y-auto">
        <div className="text-xs uppercase tracking-wider opacity-60 px-2 py-1 font-bold" style={{ color: tema.texto }}>{MEITI.t('contacts', null, 'Contactos')}</div>
        {perfiles.length === 0 ? (
          <p className="text-xs opacity-50 px-2" style={{ color: tema.texto }}>{MEITI.t('no_contacts', null, 'No hay otros usuarios registrados.')}</p>
        ) : (
          perfiles.map(p => (
            <button 
              key={p.id} 
              onClick={() => cambiarDM(p.usuario_id)}
              className="flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-bold transition-colors text-left"
              style={{ 
                backgroundColor: prefs.dm_activo === p.usuario_id ? tema.colorPrimario + '22' : 'transparent', 
                color: prefs.dm_activo === p.usuario_id ? tema.colorPrimario : tema.texto 
              }}
            >
              <img src={p.avatar_url || 'avatares/toon_1.png'} alt="avatar" className="w-6 h-6 rounded-full object-cover" />
              <span className="truncate">{p.nombre}</span>
            </button>
          ))
        )}
      </UI.Tarjeta>

      <UI.Tarjeta className="flex-1 flex flex-col min-h-0 p-0 overflow-hidden">
        {cargando && mensajes.length === 0 ? (
          <div className="flex-1 flex items-center justify-center"><Iconos.Loader className="animate-spin" color={tema.colorPrimario} /></div>
        ) : !perfilActivo ? (
          <UI.EstadoVacio icono="fa-user-group" mensaje={MEITI.t('select_contact', null, 'Selecciona un contacto para chatear')} />
        ) : (
          <>
            <div className="p-4 border-b flex items-center gap-3 shadow-sm z-10" style={{ borderColor: tema.texto + '11', backgroundColor: tema.superficie }}>
              <img src={perfilActivo.avatar_url || 'avatares/toon_1.png'} alt="avatar" className="w-10 h-10 rounded-full object-cover" />
              <div>
                <h2 className="font-bold text-lg leading-tight" style={{ color: tema.texto }}>{perfilActivo.nombre}</h2>
                <p className="text-xs opacity-60" style={{ color: tema.texto }}>{perfilActivo.cargo || 'Compañero'}</p>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-6">
              {mensajes.length === 0 ? (
                <UI.EstadoVacio icono="fa-hand-wave" mensaje={MEITI.t('no_dms_yet', null, 'Envía el primer mensaje directo.')} />
              ) : (
                mensajes.map(m => {
                  const esMio = m.autor_id === miId;
                  return (
                    <div key={m.id} className={`flex flex-col max-w-[75%] ${esMio ? 'self-end items-end' : 'self-start items-start'}`}>
                      <div className="px-4 py-2 rounded-2xl text-sm" style={{ backgroundColor: esMio ? tema.colorPrimario : tema.texto + '08', color: esMio ? '#fff' : tema.texto, borderBottomRightRadius: esMio ? '4px' : '16px', borderBottomLeftRadius: !esMio ? '4px' : '16px' }}>
                        {m.texto}
                      </div>
                      <span className="text-xs opacity-40 mt-1 px-1" style={{ color: tema.texto }}>{new Date(m.fecha_registro).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                    </div>
                  );
                })
              )}
            </div>

            <div className="p-4 border-t" style={{ borderColor: tema.texto + '11', backgroundColor: tema.superficie }}>
              <form onSubmit={enviarMensaje} className="flex gap-2">
                <div className="flex-1">
                  <UI.Campo tipo="text" valor={nuevoMensaje} onChange={e => setNuevoMensaje(e.target.value)} placeholder={MEITI.t('type_dm', { nombre: perfilActivo.nombre }, 'Mensaje para {nombre}...')} />
                </div>
                <UI.Boton tipo="submit" variante="primario" disabled={enviando || !nuevoMensaje.trim()}>
                  <Iconos.Send size={18} />
                </UI.Boton>
              </form>
            </div>
          </>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();
  const [canales, setCanales] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);
  const [form, setForm] = useState({ id: '', nombre: '', descripcion: '', tipo: 'publico' });

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}`);
    if (res.ok) setCanales(res.registros);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null); setExito(null);
    if (!form.nombre.trim()) return setError(MEITI.t('channel_name_req', null, 'El nombre del canal es obligatorio.'));

    const payload = {
      id: form.id || `can_${Date.now()}`,
      nombre: form.nombre.trim().toLowerCase().replace(/\s+/g, '-'),
      descripcion: form.descripcion.trim(),
      tipo: form.tipo,
      creador_id: miId,
      fecha_creacion: form.id ? undefined : new Date().toISOString()
    };

    const res = await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}`, {
      method: form.id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(form.id ? MEITI.t('channel_updated', null, 'Canal actualizado.') : MEITI.t('channel_created', null, 'Canal creado.'));
        setForm({ id: '', nombre: '', descripcion: '', tipo: 'publico' });
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('error_saving', null, 'Error al guardar.'))
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('delete_channel_q', null, '¿Borrar este canal y todos sus mensajes?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null); setExito(null);
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => {
        setExito(MEITI.t('channel_deleted', null, 'Canal borrado.'));
        if (form.id === id) setForm({ id: '', nombre: '', descripcion: '', tipo: 'publico' });
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('error_deleting', null, 'Error al borrar.'))
    });
  };

  const editar = (fila) => {
    setForm({ id: fila.id, nombre: fila.nombre, descripcion: fila.descripcion || '', tipo: fila.tipo || 'publico' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const columnas = [
    { clave: 'nombre', etiqueta: MEITI.t('name', null, 'Nombre'), render: (f) => <span className="font-bold">#{f.nombre}</span> },
    { clave: 'descripcion', etiqueta: MEITI.t('description', null, 'Descripción') },
    { clave: 'tipo', etiqueta: MEITI.t('type', null, 'Tipo'), render: (f) => <UI.Chip tono={f.tipo === 'publico' ? 'exito' : 'alerta'}>{f.tipo}</UI.Chip> },
    { clave: 'fecha_creacion', etiqueta: MEITI.t('created', null, 'Creado'), tipo: 'fecha' }
  ];

  return (
    <div className="flex flex-col gap-6">
      <UI.Tarjeta>
        <div className="flex items-center gap-2 mb-4">
          <Iconos.Hash size={20} color={tema.colorPrimario} />
          <UI.Etiqueta>{form.id ? MEITI.t('edit_channel', null, 'Editar Canal') : MEITI.t('new_channel', null, 'Nuevo Canal')}</UI.Etiqueta>
        </div>
        <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
        <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />
        <form onSubmit={guardar} className="flex flex-col gap-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('channel_name', null, 'Nombre del canal')} tipo="text" valor={form.nombre} onChange={e => setForm({...form, nombre: e.target.value})} placeholder="ej: anuncios-generales" />
            </div>
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('visibility', null, 'Visibilidad')} tipo="select" valor={form.tipo} onChange={e => setForm({...form, tipo: e.target.value})} opciones={[{value:'publico', label: MEITI.t('public', null, 'Público')}, {value:'privado', label: MEITI.t('private', null, 'Privado')}]} />
            </div>
            <div className="md:col-span-3 flex-1">
              <UI.Campo etiqueta={MEITI.t('description', null, 'Descripción')} tipo="text" valor={form.descripcion} onChange={e => setForm({...form, descripcion: e.target.value})} placeholder="Propósito de este canal" />
            </div>
          </div>
          <div className="flex gap-2">
            <UI.Boton tipo="submit" variante="primario">{form.id ? MEITI.t('update', null, 'Actualizar') : MEITI.t('create', null, 'Crear')}</UI.Boton>
            {form.id && <UI.Boton tipo="button" variante="secundario" onClick={() => setForm({ id: '', nombre: '', descripcion: '', tipo: 'publico' })}>{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton>}
          </div>
        </form>
      </UI.Tarjeta>

      <UI.Tarjeta>
        <UI.Etiqueta>{MEITI.t('directory', null, 'Directorio de Canales')}</UI.Etiqueta>
        {cargando ? <p style={{color: tema.texto}} className="mt-4">{MEITI.t('loading', null, 'Cargando...')}</p> : canales.length === 0 ? <UI.EstadoVacio icono="fa-hashtag" mensaje={MEITI.t('no_channels', null, 'No hay canales creados.')} /> : (
          <div className="mt-4">
            <UI.TablaDatos columnas={columnas} datos={canales} claveId="id" onEditar={editar} onBorrar={(fila) => borrar(fila.id)} />
          </div>
        )}
      </UI.Tarjeta>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const miId = MEITI.obtenerUsuarioActual();

  const [termino, setTermino] = useState('');
  const [filtroCanal, setFiltroCanal] = useState('');
  const [filtroAutor, setFiltroAutor] = useState('');
  const [filtroDesde, setFiltroDesde] = useState('');
  const [filtroHasta, setFiltroHasta] = useState('');
  const [soloArchivos, setSoloArchivos] = useState('0');

  const [canales, setCanales] = useState([]);
  const [perfiles, setPerfiles] = useState([]);
  const [resultados, setResultados] = useState([]);
  const [buscado, setBuscado] = useState(false);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargarFiltros = async () => {
      const [resCanales, resPerfiles] = await Promise.all([
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_canales')}?ecosistema=${eco}`),
        MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_perfiles')}?ecosistema=${eco}`)
      ]);
      if (resCanales.ok) setCanales(resCanales.registros || []);
      if (resPerfiles.ok) setPerfiles(resPerfiles.registros || []);
    };
    cargarFiltros();
  }, []);

  const ejecutarBusqueda = async (e) => {
    if (e) e.preventDefault();
    setCargando(true);
    setError(null);
    setBuscado(true);

    const resMsg = await MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_mensajes')}?ecosistema=${eco}`);
    if (!resMsg.ok) {
      setError(resMsg.error || MEITI.t('search_error', null, 'No se pudieron cargar los mensajes para buscar.'));
      setCargando(false);
      return;
    }

    let filtrados = resMsg.registros || [];

    if (termino.trim()) {
      const t = termino.toLowerCase();
      filtrados = filtrados.filter(m => (m.texto || '').toLowerCase().includes(t));
    }
    if (filtroCanal) {
      filtrados = filtrados.filter(m => m.canal_id === filtroCanal);
    }
    if (filtroAutor) {
      filtrados = filtrados.filter(m => m.autor_id === filtroAutor);
    }
    if (soloArchivos === '1') {
      filtrados = filtrados.filter(m => m.adjunto_url && m.adjunto_url.trim() !== '');
    }
    if (filtroDesde) {
      filtrados = filtrados.filter(m => new Date(m.fecha_registro) >= new Date(filtroDesde));
    }
    if (filtroHasta) {
      const hasta = new Date(filtroHasta);
      hasta.setDate(hasta.getDate() + 1);
      filtrados = filtrados.filter(m => new Date(m.fecha_registro) < hasta);
    }

    setResultados(filtrados.sort((a, b) => new Date(b.fecha_registro) - new Date(a.fecha_registro)));
    setCargando(false);
  };

  const irAlContexto = async (msg) => {
    if (msg.canal_id) {
      const resPref = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`);
      let pref = (resPref.ok && resPref.registros.length > 0) ? resPref.registros[0] : { id: 'pref_' + miId, usuario_id: miId };
      pref.canal_activo = msg.canal_id;

      await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_preferencias')}?ecosistema=${eco}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(pref)
      }, {
        alLograr: () => MEITI.irAPagina('canal'),
        alFallar: (err) => setError(err || MEITI.t('nav_error', null, 'No se pudo navegar al canal.'))
      });
    } else if (msg.receptor_id) {
      MEITI.irAPagina('mensajes_directos');
    }
  };

  const obtenerPerfil = (autorId) => perfiles.find(p => p.usuario_id === autorId || p.id === autorId) || {};
  const obtenerCanal = (canalId) => canales.find(c => c.id === canalId) || {};

  return (
    <div className="flex flex-col gap-6 h-full min-h-0">
      <Animacion.motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-3 mb-2">
            <Iconos.Search size={24} color={tema.colorPrimario} />
            <h2 className="text-xl font-black tracking-tight" style={{ color: tema.texto }}>
              {MEITI.t('search_title', null, 'Búsqueda Avanzada')}
            </h2>
          </div>

          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

          <form onSubmit={ejecutarBusqueda} className="flex flex-col gap-4">
            <div className="flex flex-col md:flex-row gap-4 items-end">
              <div className="flex-1 w-full">
                <UI.Campo 
                  etiqueta={MEITI.t('search_term', null, 'Palabra clave o frase')}
                  tipo="text"
                  valor={termino}
                  onChange={(e) => setTermino(e.target.value)}
                  placeholder={MEITI.t('search_placeholder', null, 'Ej: reporte de ventas...')}
                />
              </div>
              <div className="w-full md:w-auto">
                <UI.Boton tipo="submit" variante="primario" disabled={cargando}>
                  <span className="flex items-center gap-2">
                    {cargando ? <Iconos.LoaderCircle size={18} className="animate-spin" /> : <Iconos.Search size={18} />}
                    {cargando ? MEITI.t('searching', null, 'Buscando...') : MEITI.t('search_btn', null, 'Buscar')}
                  </span>
                </UI.Boton>
              </div>
            </div>

            <div className="p-4 rounded-xl flex flex-col gap-4" style={{ backgroundColor: tema.fondo, border: `1px solid ${tema.colorPrimario}22` }}>
              <div className="flex items-center gap-2 opacity-70">
                <Iconos.Filter size={16} color={tema.texto} />
                <UI.Etiqueta>{MEITI.t('filters_title', null, 'Filtros adicionales')}</UI.Etiqueta>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="flex-1">
                  <UI.Campo 
                    etiqueta={MEITI.t('filter_channel', null, 'Canal')}
                    tipo="select"
                    valor={filtroCanal}
                    onChange={(e) => setFiltroCanal(e.target.value)}
                    opciones={[{ value: '', label: MEITI.t('all_channels', null, 'Todos los canales') }, ...canales.map(c => ({ value: c.id, label: c.nombre }))]}
                  />
                </div>
                <div className="flex-1">
                  <UI.Campo 
                    etiqueta={MEITI.t('filter_author', null, 'Autor')}
                    tipo="select"
                    valor={filtroAutor}
                    onChange={(e) => setFiltroAutor(e.target.value)}
                    opciones={[{ value: '', label: MEITI.t('all_authors', null, 'Cualquier autor') }, ...perfiles.map(p => ({ value: p.usuario_id || p.id, label: p.nombre }))]}
                  />
                </div>
                <div className="flex-1">
                  <UI.Campo 
                    etiqueta={MEITI.t('filter_date_from', null, 'Desde')}
                    tipo="date"
                    valor={filtroDesde}
                    onChange={(e) => setFiltroDesde(e.target.value)}
                  />
                </div>
                <div className="flex-1">
                  <UI.Campo 
                    etiqueta={MEITI.t('filter_date_to', null, 'Hasta')}
                    tipo="date"
                    valor={filtroHasta}
                    onChange={(e) => setFiltroHasta(e.target.value)}
                  />
                </div>
              </div>

              <div className="flex-1 md:w-1/4">
                <UI.Campo 
                  etiqueta={MEITI.t('filter_attachments', null, 'Archivos adjuntos')}
                  tipo="select"
                  valor={soloArchivos}
                  onChange={(e) => setSoloArchivos(e.target.value)}
                  opciones={[
                    { value: '0', label: MEITI.t('attach_any', null, 'Mostrar todos') },
                    { value: '1', label: MEITI.t('attach_only', null, 'Solo mensajes con archivos') }
                  ]}
                />
              </div>
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <div className="flex flex-col flex-1 min-h-0">
        {buscado && (
          <div className="mb-3 flex items-center justify-between">
            <UI.Etiqueta>{MEITI.t('results_title', null, 'Resultados de la búsqueda')}</UI.Etiqueta>
            <UI.Chip tono="neutro">
              {MEITI.t('results_count', { n: resultados.length }, '{n} encontrados')}
            </UI.Chip>
          </div>
        )}

        <div className="flex-1 overflow-y-auto min-h-0 pr-2 flex flex-col gap-3">
          {!buscado && !cargando && (
            <UI.EstadoVacio 
              icono="fa-magnifying-glass" 
              mensaje={MEITI.t('search_empty_state', null, 'Ingresa tus criterios arriba y presiona Buscar para encontrar mensajes o archivos.')} 
            />
          )}

          {buscado && !cargando && resultados.length === 0 && (
            <UI.EstadoVacio 
              icono="fa-inbox" 
              mensaje={MEITI.t('search_no_results', null, 'No se encontraron mensajes que coincidan con los filtros.')} 
            />
          )}

          <Animacion.AnimatePresence>
            {resultados.map((msg, index) => {
              const perfil = obtenerPerfil(msg.autor_id);
              const canal = obtenerCanal(msg.canal_id);
              const avatarUrl = perfil.avatar_url || 'avatares/memo_1.png';
              const fecha = new Date(msg.fecha_registro).toLocaleString();

              return (
                <Animacion.motion.div
                  key={msg.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.2, delay: index < 10 ? index * 0.05 : 0 }}
                >
                  <div 
                    onClick={() => irAlContexto(msg)}
                    className="p-4 rounded-2xl cursor-pointer transition-all hover:scale-[1.01] shadow-sm hover:shadow-md flex flex-col gap-3"
                    style={{ backgroundColor: tema.superficie, border: `1px solid ${tema.texto}11` }}
                  >
                    <div className="flex justify-between items-start gap-4">
                      <div className="flex items-center gap-3">
                        <img src={avatarUrl} alt={perfil.nombre || 'Usuario'} className="w-10 h-10 rounded-full object-cover bg-black/5" />
                        <div className="flex flex-col">
                          <span className="font-bold text-sm" style={{ color: tema.texto }}>{perfil.nombre || MEITI.t('unknown_user', null, 'Usuario desconocido')}</span>
                          <span className="text-xs opacity-60 font-mono" style={{ color: tema.texto }}>{fecha}</span>
                        </div>
                      </div>
                      {canal.nombre && (
                        <UI.Chip tono="neutro">
                          <span className="flex items-center gap-1">
                            <Iconos.Hash size={12} /> {canal.nombre}
                          </span>
                        </UI.Chip>
                      )}
                    </div>

                    <p className="text-sm whitespace-pre-wrap leading-relaxed" style={{ color: tema.texto }}>
                      {msg.texto}
                    </p>

                    {msg.adjunto_url && (
                      <div className="flex items-center gap-2 p-2 rounded-lg mt-1 w-fit" style={{ backgroundColor: tema.fondo, border: `1px solid ${tema.colorPrimario}33` }}>
                        <Iconos.Paperclip size={16} color={tema.colorPrimario} />
                        <span className="text-xs font-bold" style={{ color: tema.colorPrimario }}>
                          {MEITI.t('attachment_included', null, 'Archivo adjunto')}
                        </span>
                      </div>
                    )}
                  </div>
                </Animacion.motion.div>
              );
            })}
          </Animacion.AnimatePresence>
        </div>
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const esAdmin = MEITI.miRolEnLaApp() === 'admin' || MEITI.soyDuenoDeLaApp();

  const [pestana, setPestana] = useState('temas');
  const [temasCat, setTemasCat] = useState([]);
  const [estados, setEstados] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const formVacioTema = { id: '', nombre: '', icono: '' };
  const formVacioEstado = { id: '', nombre: '', icono: '', color: '#10b981' };
  const [formTema, setFormTema] = useState(formVacioTema);
  const [formEstado, setFormEstado] = useState(formVacioEstado);
  const [guardando, setGuardando] = useState(false);

  const cargarDatos = async () => {
    setCargando(true);
    const [resTemas, resEstados] = await Promise.all([
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_temas')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_estados')}?ecosistema=${eco}`)
    ]);
    if (resTemas.ok) setTemasCat(resTemas.registros || []);
    if (resEstados.ok) setEstados(resEstados.registros || []);
    setCargando(false);
  };

  useEffect(() => {
    if (esAdmin) cargarDatos();
  }, [esAdmin]);

  if (!esAdmin) {
    return <UI.Aviso tono="peligro" mensaje={MEITI.t('admin_only', null, 'Acceso denegado: Esta sección es solo para administradores.')} />;
  }

  const guardarTema = async (e) => {
    e.preventDefault();
    if (!formTema.nombre.trim()) return setError(MEITI.t('err_name_req', null, 'El nombre es obligatorio.'));
    setGuardando(true); setError(null); setExito(null);
    const esNuevo = !formTema.id;
    const payload = { ...formTema, id: esNuevo ? 'tema_' + Date.now() : formTema.id };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_temas')}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { 
        setExito(MEITI.t('tema_saved', null, 'Tema guardado correctamente.')); 
        setFormTema(formVacioTema); 
        cargarDatos(); 
        setGuardando(false); 
      },
      alFallar: (err) => { 
        setError(err || MEITI.t('err_saving', null, 'Error al guardar el tema.')); 
        setGuardando(false); 
      }
    });
  };

  const guardarEstado = async (e) => {
    e.preventDefault();
    if (!formEstado.nombre.trim()) return setError(MEITI.t('err_name_req', null, 'El nombre es obligatorio.'));
    setGuardando(true); setError(null); setExito(null);
    const esNuevo = !formEstado.id;
    const payload = { ...formEstado, id: esNuevo ? 'est_' + Date.now() : formEstado.id };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_estados')}?ecosistema=${eco}`, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => { 
        setExito(MEITI.t('estado_saved', null, 'Estado guardado correctamente.')); 
        setFormEstado(formVacioEstado); 
        cargarDatos(); 
        setGuardando(false); 
      },
      alFallar: (err) => { 
        setError(err || MEITI.t('err_saving', null, 'Error al guardar el estado.')); 
        setGuardando(false); 
      }
    });
  };

  const borrarTema = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('del_tema_q', null, '¿Borrar este tema?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null); setExito(null);
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_temas')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => { 
        setExito(MEITI.t('tema_deleted', null, 'Tema eliminado.')); 
        if (formTema.id === id) setFormTema(formVacioTema); 
        cargarDatos(); 
      },
      alFallar: (err) => setError(err || MEITI.t('err_deleting', null, 'Error al eliminar.'))
    });
  };

  const borrarEstado = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('del_estado_q', null, '¿Borrar este estado?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null); setExito(null);
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('rc_catalogos_estados')}?ecosistema=${eco}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => { 
        setExito(MEITI.t('estado_deleted', null, 'Estado eliminado.')); 
        if (formEstado.id === id) setFormEstado(formVacioEstado); 
        cargarDatos(); 
      },
      alFallar: (err) => setError(err || MEITI.t('err_deleting', null, 'Error al eliminar.'))
    });
  };

  const editarTema = (fila) => {
    setFormTema({ id: fila.id, nombre: fila.nombre || '', icono: fila.icono || '' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const editarEstado = (fila) => {
    setFormEstado({ id: fila.id, nombre: fila.nombre || '', icono: fila.icono || '', color: fila.color || '#10b981' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const colsTemas = [
    { clave: 'icono', etiqueta: MEITI.t('col_icon', null, 'Ícono'), render: (f) => f.icono ? <i className={`fa-solid ${f.icono}`} style={{ color: tema.colorPrimario }}></i> : '-' },
    { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') }
  ];

  const colsEstados = [
    { clave: 'icono', etiqueta: MEITI.t('col_icon', null, 'Ícono'), render: (f) => f.icono ? <i className={`fa-solid ${f.icono}`} style={{ color: f.color || tema.texto }}></i> : '-' },
    { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') },
    { clave: 'color', etiqueta: MEITI.t('col_color', null, 'Color'), render: (f) => (
      <div className="flex items-center gap-2">
        <div className="w-4 h-4 rounded-full" style={{ backgroundColor: f.color || tema.texto }}></div>
        <span className="text-xs font-mono opacity-70">{f.color}</span>
      </div>
    )}
  ];

  return (
    <div className="flex flex-col gap-6">
      <UI.Pestanas 
        pestanas={[
          { id: 'temas', titulo: MEITI.t('tab_temas', null, 'Temas de Canales'), icono: 'fa-hashtag' },
          { id: 'estados', titulo: MEITI.t('tab_estados', null, 'Estados de Personal'), icono: 'fa-user-clock' }
        ]}
        activa={pestana}
        onCambio={(p) => { setPestana(p); setError(null); setExito(null); }}
      />

      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

      <Animacion.AnimatePresence mode="wait">
        {pestana === 'temas' && (
          <Animacion.motion.div key="temas" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }} className="flex flex-col gap-6">
            <UI.Tarjeta>
              <div className="flex items-center gap-2 mb-4">
                <Iconos.Hash size={20} color={tema.colorPrimario} />
                <UI.Etiqueta>{formTema.id ? MEITI.t('edit_tema', null, 'Editar Tema') : MEITI.t('new_tema', null, 'Nuevo Tema')}</UI.Etiqueta>
              </div>
              <form onSubmit={guardarTema} className="flex flex-col gap-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="flex-1">
                    <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre del tema')} tipo="text" valor={formTema.nombre} onChange={e => setFormTema({...formTema, nombre: e.target.value})} placeholder={MEITI.t('ph_tema_name', null, 'Ej: General, Soporte')} />
                  </div>
                  <div className="flex-1">
                    <UI.Campo etiqueta={MEITI.t('f_icon', null, 'Clase de Ícono (FontAwesome)')} tipo="text" valor={formTema.icono} onChange={e => setFormTema({...formTema, icono: e.target.value})} placeholder="fa-hashtag" />
                  </div>
                </div>
                <div className="flex gap-2 mt-2">
                  <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                    <span className="flex items-center gap-2"><Iconos.Save size={16} /> {guardando ? MEITI.t('saving', null, 'Guardando...') : (formTema.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear Tema'))}</span>
                  </UI.Boton>
                  {formTema.id && (
                    <UI.Boton tipo="button" variante="secundario" onClick={() => setFormTema(formVacioTema)}>
                      <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                    </UI.Boton>
                  )}
                </div>
              </form>
            </UI.Tarjeta>

            <UI.Tarjeta className="flex flex-col flex-1 min-h-0">
              <UI.Etiqueta>{MEITI.t('list_temas', null, 'Temas Registrados')}</UI.Etiqueta>
              <div className="mt-4 flex-1 min-h-0">
                {cargando ? (
                  <p style={{color: tema.texto}} className="opacity-70">{MEITI.t('loading', null, 'Cargando...')}</p>
                ) : temasCat.length === 0 ? (
                  <UI.EstadoVacio icono="fa-hashtag" mensaje={MEITI.t('empty_temas', null, 'No hay temas registrados.')} />
                ) : (
                  <UI.TablaDatos columnas={colsTemas} datos={temasCat} claveId="id" onEditar={editarTema} onBorrar={(fila) => borrarTema(fila.id)} />
                )}
              </div>
            </UI.Tarjeta>
          </Animacion.motion.div>
        )}

        {pestana === 'estados' && (
          <Animacion.motion.div key="estados" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }} className="flex flex-col gap-6">
            <UI.Tarjeta>
              <div className="flex items-center gap-2 mb-4">
                <Iconos.UserCog size={20} color={tema.colorPrimario} />
                <UI.Etiqueta>{formEstado.id ? MEITI.t('edit_estado', null, 'Editar Estado') : MEITI.t('new_estado', null, 'Nuevo Estado')}</UI.Etiqueta>
              </div>
              <form onSubmit={guardarEstado} className="flex flex-col gap-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="flex-1">
                    <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre del estado')} tipo="text" valor={formEstado.nombre} onChange={e => setFormEstado({...formEstado, nombre: e.target.value})} placeholder={MEITI.t('ph_estado_name', null, 'Ej: Disponible, Ocupado')} />
                  </div>
                  <div className="flex-1">
                    <UI.Campo etiqueta={MEITI.t('f_icon', null, 'Clase de Ícono')} tipo="text" valor={formEstado.icono} onChange={e => setFormEstado({...formEstado, icono: e.target.value})} placeholder="fa-circle-check" />
                  </div>
                  <div className="flex-1">
                    <UI.Campo etiqueta={MEITI.t('f_color', null, 'Color (Hex)')} tipo="text" valor={formEstado.color} onChange={e => setFormEstado({...formEstado, color: e.target.value})} placeholder="#10b981" />
                  </div>
                </div>
                <div className="flex gap-2 mt-2">
                  <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                    <span className="flex items-center gap-2"><Iconos.Save size={16} /> {guardando ? MEITI.t('saving', null, 'Guardando...') : (formEstado.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear Estado'))}</span>
                  </UI.Boton>
                  {formEstado.id && (
                    <UI.Boton tipo="button" variante="secundario" onClick={() => setFormEstado(formVacioEstado)}>
                      <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                    </UI.Boton>
                  )}
                </div>
              </form>
            </UI.Tarjeta>

            <UI.Tarjeta className="flex flex-col flex-1 min-h-0">
              <UI.Etiqueta>{MEITI.t('list_estados', null, 'Estados Registrados')}</UI.Etiqueta>
              <div className="mt-4 flex-1 min-h-0">
                {cargando ? (
                  <p style={{color: tema.texto}} className="opacity-70">{MEITI.t('loading', null, 'Cargando...')}</p>
                ) : estados.length === 0 ? (
                  <UI.EstadoVacio icono="fa-user-clock" mensaje={MEITI.t('empty_estados', null, 'No hay estados registrados.')} />
                ) : (
                  <UI.TablaDatos columnas={colsEstados} datos={estados} claveId="id" onEditar={editarEstado} onBorrar={(fila) => borrarEstado(fila.id)} />
                )}
              </div>
            </UI.Tarjeta>
          </Animacion.motion.div>
        )}
      </Animacion.AnimatePresence>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('configuracion_app');

  // 👑 El dueño SIEMPRE cuenta como admin, no solo quien esté en la tabla de roles. Es la regla que
  // ya costó caro una vez: un panel que mira nada más la tabla deja al dueño afuera de su propia
  // app apenas cambia de email.
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [pestana, setPestana] = React.useState('ayuda');
  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [aviso, setAviso] = React.useState(null);

  // Un solo formulario para las dos pestañas: lo que cambia es la sección donde escribe.
  const VACIO = { titulo: '', cuerpo: '', tono: 'neutro' };
  const [editando, setEditando] = React.useState(null);
  const [forma, setForma] = React.useState(VACIO);
  const [abierto, setAbierto] = React.useState(false);

  const cargar = async () => {
    setCargando(true);
    const r = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (r.ok) setFilas(r.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const cerrarFormulario = () => { setAbierto(false); setEditando(null); setForma(VACIO); };

  const guardar = async () => {
    if (!forma.titulo.trim()) { setAviso('Ponle un título antes de guardar.'); return; }
    const fila = editando || {};
    // 🩹 /api/boveda hace INSERT OR REPLACE por "id": si no se mandan TODAS las columnas, las que
    // falten quedan en NULL al reemplazar. Por eso el cuerpo va completo siempre, no solo lo tocado.
    const cuerpo = {
      id: fila.id || (pestana + '_' + Date.now()),
      seccion: pestana,
      titulo: forma.titulo.trim(),
      cuerpo: forma.cuerpo,
      tono: forma.tono || 'neutro',
      orden: fila.orden != null ? fila.orden : filas.filter(f => f.seccion === pestana).length,
      fecha: fila.fecha || new Date().toISOString()
    };
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + (editando ? '&id=' + fila.id : ''), {
      method: editando ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cuerpo)
    });
    if (r && r.ok === false) { setAviso('No se pudo guardar. Vuelve a intentarlo.'); return; }
    setAviso(null);
    cerrarFormulario();
    cargar();
  };

  const borrar = async (fila) => {
    if (!await MEITI.confirmar('¿Borrar "' + (fila.titulo || 'este registro') + '"?', { titulo: MEITI.t('delete_action', null, 'Borrar'), confirmar: MEITI.t('delete_confirm', null, 'Sí, borrar'), tono: 'peligro' })) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo borrar. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const abrirEdicion = (fila) => {
    setEditando(fila);
    setForma({ titulo: fila.titulo || '', cuerpo: fila.cuerpo || '', tono: fila.tono || 'neutro' });
    setAbierto(true);
  };

  const deLaSeccion = filas.filter(f => (f.seccion || 'ayuda') === pestana);
  // La ayuda se lee en el orden en que el dueño la escribió; la bitácora, al revés: lo último
  // que pasó es lo primero que uno quiere ver.
  const visibles = pestana === 'ayuda'
    ? deLaSeccion.slice().sort((a, b) => (a.orden || 0) - (b.orden || 0))
    : deLaSeccion.slice().sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));

  const fechaLegible = (v) => {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || ''));
    if (!m) return '';
    const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    return Number(m[3]) + ' ' + MESES[Number(m[2]) - 1] + ' ' + m[1];
  };

  const TONOS = [
    { value: 'neutro', label: MEITI.t('note_input', null, 'Nota') },
    { value: 'exito', label: MEITI.t('update_input', null, 'Actualización') },
    { value: 'alerta', label: MEITI.t('notice_input', null, 'Aviso') },
    { value: 'peligro', label: MEITI.t('error_input', null, 'Error') }
  ];
  const nombreDelTono = (t) => (TONOS.find(x => x.value === (t || 'neutro')) || TONOS[0]).label;

  const filaAyuda = (f) => (
    <div key={f.id} style={{ border: '1px solid ' + tema.colorPrimario + '22', borderRadius: '0.75rem', padding: '1rem', marginBottom: '0.75rem' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem' }}>
        <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        {soyAdmin && (
          <div style={{ display: 'flex', gap: '0.25rem', flexShrink: 0 }}>
            <UI.Boton variante="fantasma" ariaLabel={MEITI.t('edit_action', null, "Editar")} onClick={() => abrirEdicion(f)}><i className="fa-solid fa-pen-to-square"></i></UI.Boton>
            <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>
          </div>
        )}
      </div>
      {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.8, marginTop: '0.5rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
    </div>
  );

  const filaBitacora = (f) => (
    <div key={f.id} style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem', borderBottom: '1px solid ' + tema.colorPrimario + '18', padding: '0.6rem 0' }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
          <UI.Chip tono={f.tono || 'neutro'}>{nombreDelTono(f.tono)}</UI.Chip>
          <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        </div>
        {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.75, marginTop: '0.35rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
        <span style={{ color: tema.texto, opacity: 0.5, fontSize: '0.75rem', whiteSpace: 'nowrap' }}>{fechaLegible(f.fecha)}</span>
        {soyAdmin && <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>}
      </div>
    </div>
  );

  return (
    <UI.Tarjeta>
      <h3 style={{ color: tema.texto, fontSize: '1.2rem', fontWeight: 'bold', marginBottom: '0.25rem' }}>{MEITI.t('configuration_title', null, "Configuración")}</h3>
      <p style={{ color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem' }}>{MEITI.t('app_guide_description', null, "Cómo se usa esta app, y qué le fue pasando.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      <UI.Pestanas
        pestanas={[{ id: 'ayuda', titulo: MEITI.t('help_title', null, 'Ayuda'), icono: 'fa-circle-question' }, { id: 'bitacora', titulo: MEITI.t('changelog_title', null, 'Bitácora'), icono: 'fa-clock-rotate-left' }]}
        activa={pestana}
        onCambio={(id) => { setPestana(id); cerrarFormulario(); }}
        className="mb-4"
      />

      {cargando ? (
        <p style={{ color: tema.texto, opacity: 0.6 }}>{MEITI.t('loading', null, "Cargando...")}</p>
      ) : visibles.length === 0 ? (
        <UI.EstadoVacio
          icono={pestana === 'ayuda' ? 'fa-book-open' : 'fa-clock-rotate-left'}
          mensaje={pestana === 'ayuda'
            ? (soyAdmin ? 'Todavía no hay guía de uso. Escribe la primera sección y quien entre después va a saber cómo usar la app.' : 'Todavía no hay una guía para esta app.')
            : 'Todavía no hay nada anotado. Acá van a aparecer las actualizaciones, los avisos y los errores de esta app.'}
        />
      ) : pestana === 'ayuda' ? (
        <div>{visibles.map(filaAyuda)}</div>
      ) : (
        <UI.ListaScrollable alto="26rem">{visibles.map(filaBitacora)}</UI.ListaScrollable>
      )}

      {soyAdmin && (
        <div style={{ marginTop: '1.25rem', paddingTop: '1rem', borderTop: '1px solid ' + tema.colorPrimario + '22' }}>
          {!abierto ? (
            <UI.Boton variante="secundario" onClick={() => setAbierto(true)}>
              <i className="fa-solid fa-plus"></i> {pestana === 'ayuda' ? 'Agregar una sección a la guía' : 'Anotar en la bitácora'}
            </UI.Boton>
          ) : (
            <div>
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Título de la sección' : 'Qué pasó'}
                valor={forma.titulo}
                onChange={(e) => setForma({ ...forma, titulo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Cómo dar de alta un cliente' : 'Se actualizó el catálogo de precios'}
              />
              <div style={{ height: '0.75rem' }} />
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Explicación' : 'Detalle (opcional)'}
                tipo="textarea"
                filas={4}
                valor={forma.cuerpo}
                onChange={(e) => setForma({ ...forma, cuerpo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Explícalo como se lo explicarías a alguien que abre la app por primera vez' : 'Qué se cambió y por qué'}
              />
              {pestana === 'bitacora' && (
                <div style={{ marginTop: '0.75rem' }}>
                  <UI.Campo etiqueta={MEITI.t('type_input', null, "Tipo")} tipo="select" valor={forma.tono} onChange={(e) => setForma({ ...forma, tono: e.target.value })} opciones={TONOS} />
                </div>
              )}
              <div style={{ height: '0.75rem' }} />
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <UI.Boton onClick={guardar}>{editando ? 'Guardar cambios' : 'Guardar'}</UI.Boton>
                <UI.Boton variante="secundario" onClick={cerrarFormulario}>{MEITI.t('cancel_button', null, "Cancelar")}</UI.Boton>
              </div>
            </div>
          )}
        </div>
      )}
    </UI.Tarjeta>
  );
}
